58: bool PathFinding::IsWalkable(const Vector2D& pos, const std::vector<MobInfo>& obstacles) const
59: {
60:     const float MOB_AVOIDANCE_RADIUS = 50.0f;
61:     
62:     for (const auto& mob : obstacles)
63:     {
64:         if (!mob.isAlive)
65:             continue;
66:         
67:         float dx = pos.x - mob.position.x;
68:         float dy = pos.y - mob.position.y;
69:         float distance = sqrtf(dx * dx + dy * dy);
70:         
71:         if (distance < MOB_AVOIDANCE_RADIUS)
72:             return false;
73:     }
74:     
75:     return true;
76: }
