83: bool BotEngine::FindGameProcess()
84: {
85:     PROCESSENTRY32 pe32;
86:     pe32.dwSize = sizeof(PROCESSENTRY32);
87: 
88:     HANDLE hProcessSnap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
89:     if (hProcessSnap == INVALID_HANDLE_VALUE)
90:         return false;
91: 
92:     // Look for Diablo II: Resurrected
93:      if (Process32First(hProcessSnap, &pe32))
94:      {
95:          do
96:          {
97:              if (_wcsicmp(pe32.szExeFile, L"D2R") == 0 || _wcsicmp(pe32.szExeFile, L"D2R.exe") == 0)
98:             {
99:                 m_processId = pe32.th32ProcessID;
100:                 CloseHandle(hProcessSnap);
101:                 return true;
102:             }
103:         } while (Process32Next(hProcessSnap, &pe32));
104:     }
105: 
106:     CloseHandle(hProcessSnap);
107:     return false;
108: }
