23:     namespace Player
24:     {
25:         constexpr uintptr_t POSITION_X = 0x10;                  // float x coordinate
26:         constexpr uintptr_t POSITION_Y = 0x14;                  // float y coordinate
27:         constexpr uintptr_t CLASS_TYPE = 0x20;                  // int class (0-6)
28:         constexpr uintptr_t LEVEL = 0x24;                       // int level (1-99)
29:         constexpr uintptr_t EXPERIENCE = 0x28;                  // uint64 total exp
30:         constexpr uintptr_t LIFE = 0x30;                        // int current life
31:         constexpr uintptr_t MANA = 0x34;                        // int current mana
32:         constexpr uintptr_t MAX_LIFE = 0x38;                    // int max life
33:         constexpr uintptr_t MAX_MANA = 0x3C;                    // int max mana
34:         constexpr uintptr_t DIRECTION = 0x40;                   // byte facing direction (0-255)
35:         constexpr uintptr_t MODE = 0x41;                        // byte animation mode
36:         constexpr uintptr_t STATE = 0x44;                       // int state flags
