// Execute waypoint clicks continuously
while (m_isRunning && currentRoute)
{
    for (int i = 0; i < routeLength && m_isRunning; i++)
    {
        int x = currentRoute[i].x;
        int y = currentRoute[i].y;

        // Add some randomness to avoid detection
        int randX = (rand() % 15) - 7;   // ±7 pixels
        int randY = (rand() % 15) - 7;

        x += randX;
        y += randY;

        // Clamp to reasonable screen bounds (game area)
        if (x < 400) x = 400;
        if (x > 1000) x = 1000;
        if (y < 200) y = 200;
        if (y > 700) y = 700;

        // Left-click at waypoint (movement click)
        SetCursorPos(x, y);
        Sleep(50 + (rand() % 80));  // Variable delay
        mouse_event(MOUSEEVENTF_LEFTDOWN, 0, 0, 0, 0);
        Sleep(20 + (rand() % 40));
        mouse_event(MOUSEEVENTF_LEFTUP, 0, 0, 0, 0);
        Sleep(400 + (rand() % 300));  // Wait for character to move
    }
}

